#!/usr/bin/env node
/**
 * scripts/apply-seo-opportunities-2026-W25.mjs
 *
 * Applies the reviewed, RE-TRIAGED high-value meta rewrite from the
 * 2026-W25 SEO agent run. NB: the W25 opportunities were generated by the
 * pre-fix logic that mislabelled types (see PR #57), so they were re-triaged
 * by hand. Only the changes pinned below are applied — the rest of the W25
 * batch is left for manual review.
 *
 * Approvals applied here:
 *   hedge trimming in hampshire → services.id 6 (hedge-cutting)
 *     The page's stored meta was broken: title was a bare "Hedge Cutting"
 *     and the description was auto-concatenated headings. Rewrite to target
 *     the actual query ("hedge trimming") + location, with a real CTA.
 *
 * Where used, also flips the matching seo-opportunities row to 'completed'
 * (looked up by query + weekIdentified, best-effort — won't fail the run).
 *
 * Idempotent. Dry-run by default; pass --execute to write.
 *
 * Run against prod (tsx loads the TS payload config):
 *   DATABASE_URL=$DATABASE_URL_PROD node_modules/.bin/tsx scripts/apply-seo-opportunities-2026-W25.mjs --execute
 */
import { getPayload } from 'payload';
import config from '../src/payload/payload.config.ts';

const EXECUTE = process.argv.includes('--execute');

const WEEK = '2026-W25';

const UPDATES = [
  {
    query: 'hedge trimming in hampshire',
    collection: 'services',
    targetId: 6,
    metaTitle: 'Hedge Cutting & Trimming in Hampshire',
    metaDescription:
      'Hedge cutting and trimming across Hampshire and the South of England. Keep paddock boundaries tidy, stockproof and safe — get in touch to book your hedges in.',
  },
];

const payload = await getPayload({ config });

console.log(EXECUTE ? '[execute] writing meta updates + marking completed' : '[dry-run] use --execute to write');
console.log();

let updated = 0;
let unchanged = 0;
let missing = 0;
let opportunitiesCompleted = 0;

for (const u of UPDATES) {
  const doc = await payload
    .findByID({ collection: u.collection, id: u.targetId, depth: 0 })
    .catch(() => null);

  if (!doc) {
    console.log(`  [missing] ${u.collection}/${u.targetId}`);
    missing++;
    continue;
  }

  const cur = doc.seo ?? {};
  const sameTitle = cur.metaTitle === u.metaTitle;
  const sameDesc = cur.metaDescription === u.metaDescription;
  const slug = doc.slug ?? '(no-slug)';

  if (sameTitle && sameDesc) {
    console.log(`  [unchanged] ${u.collection}/${slug}`);
    unchanged++;
  } else {
    console.log(`  [update] ${u.collection}/${slug}`);
    console.log(`    title was:  "${cur.metaTitle ?? '(none)'}"`);
    console.log(`    title now:  "${u.metaTitle}"`);
    console.log(`    desc was:   "${(cur.metaDescription ?? '(none)').slice(0, 100)}..."`);
    console.log(`    desc now:   "${u.metaDescription.slice(0, 100)}..."`);

    if (EXECUTE) {
      try {
        await payload.update({
          collection: u.collection,
          id: u.targetId,
          data: { seo: { ...cur, metaTitle: u.metaTitle, metaDescription: u.metaDescription } },
        });
        updated++;
      } catch (err) {
        console.error(`    error: ${err instanceof Error ? err.message : err}`);
        continue;
      }
    }
  }

  if (EXECUTE) {
    // Best-effort: mark the matching opportunity completed (looked up by query).
    try {
      const found = await payload.find({
        collection: 'seo-opportunities',
        where: { and: [{ query: { equals: u.query } }, { weekIdentified: { equals: WEEK } }] },
        limit: 2,
        depth: 0,
      });
      if (found.docs.length === 1) {
        await payload.update({
          collection: 'seo-opportunities',
          id: found.docs[0].id,
          data: { status: 'completed', decidedAt: new Date().toISOString() },
        });
        opportunitiesCompleted++;
      } else {
        console.log(`    [opp] ${found.docs.length} matches for "${u.query}" ${WEEK} — not flipping status`);
      }
    } catch (err) {
      console.error(`    [opp] lookup/update failed: ${err instanceof Error ? err.message : err}`);
    }
  }
}

console.log(
  `\nDone — ${updated} updated, ${unchanged} unchanged, ${missing} missing, ${opportunitiesCompleted} opportunities marked completed`,
);
process.exit(0);
